class Solution {
  public int reachableNodes(int[][] edges, int maxMoves, int n) {
    java.util.List<int[]>[] g = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) g[i] = new java.util.ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(new int[] {e[1], e[2]});
      g[e[1]].add(new int[] {e[0], e[2]});
    }
    long[] dist = new long[n];
    java.util.Arrays.fill(dist, Long.MAX_VALUE);
    dist[0] = 0;
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
    pq.add(new long[] {0, 0});
    while (!pq.isEmpty()) {
      long[] cur = pq.poll();
      long d = cur[0];
      int u = (int) cur[1];
      if (d != dist[u]) continue;
      for (int[] e : g[u]) {
        long nd = d + e[1] + 1;
        if (nd < dist[e[0]]) {
          dist[e[0]] = nd;
          pq.add(new long[] {nd, e[0]});
        }
      }
    }
    int ans = 0;
    for (long d : dist) if (d <= maxMoves) ans++;
    for (int[] e : edges) {
      long a = dist[e[0]] > maxMoves ? 0 : maxMoves - dist[e[0]],
          b = dist[e[1]] > maxMoves ? 0 : maxMoves - dist[e[1]];
      ans += Math.min(e[2], a + b);
    }
    return ans;
  }
}
